css:
.on-photo{font-family:"Noto Serif JP",serif; color:#fff; letter-spacing:.08em; line-height:1.6;
  text-shadow:0 2px 12px rgba(0,0,0,.45), 0 0 2px rgba(0,0,0,.25)}
/* スクリムを足すとしても文字の行だけに限定する */
.on-photo::before{content:''; position:absolute; inset:auto 0 0 0; height:38%;
  background:linear-gradient(transparent, rgba(0,0,0,.28))}
